using System;using System.Drawing;using System.Diagnostics;using System.Reflection;using System.Runtime.InteropServices;using System.Windows.Forms;
class RenderCompare {
[DllImport("opengl32.dll")]static extern void glFinish();
[DllImport("opengl32.dll")]static extern void glReadBuffer(uint mode);
[DllImport("opengl32.dll")]static extern void glReadPixels(int x,int y,int w,int h,uint format,uint type,byte[] data);
static Tuple<byte[],double> Run(string path,int fixture){var assembly=Assembly.LoadFile(path);var rendererType=assembly.GetType("SensitivityFinder.ArenaRenderer");var frameType=assembly.GetType("SensitivityFinder.ArenaFrame");using(var form=new Form()){form.ClientSize=new Size(640,360);var renderer=(IDisposable)Activator.CreateInstance(rendererType,new object[]{form.Handle});using(renderer){var frame=Activator.CreateInstance(frameType);foreach(var pair in new[]{new[]{"Title","Fixture"},new[]{"Hint","No input"},new[]{"Timer","12.3"},new[]{"Score","4"}})frameType.GetField(pair[0]).SetValue(frame,pair[1]);frameType.GetField("Lesson").SetValue(frame,fixture==1);frameType.GetField("LessonTitle").SetValue(frame,"Synthetic lesson");var render=rendererType.GetMethod("Render");var args=new object[]{640,360,frame};for(int i=0;i<30;i++)render.Invoke(renderer,args);glFinish();var clock=Stopwatch.StartNew();for(int i=0;i<300;i++)render.Invoke(renderer,args);glFinish();clock.Stop();var pixels=new byte[640*360*4];glReadBuffer(0x0404);glReadPixels(0,0,640,360,0x1908,0x1401,pixels);return Tuple.Create(pixels,clock.Elapsed.TotalMilliseconds);}}}
[STAThread]static int Main(string[] args){try{for(int fixture=0;fixture<2;fixture++){var before=Run(args[0],fixture);var after=Run(args[1],fixture);int mismatches=0,nonzero=0;for(int i=0;i<before.Item1.Length;i++){if(before.Item1[i]!=after.Item1[i])mismatches++;if(before.Item1[i]!=0)nonzero++;}Console.WriteLine("Fixture "+fixture+": baseline "+before.Item2.ToString("F1")+"ms / optimized "+after.Item2.ToString("F1")+"ms for 300 frames; mismatched bytes="+mismatches+"; nonzero bytes="+nonzero);if(mismatches!=0||nonzero==0)return 1;}return 0;}catch(Exception e){Console.WriteLine(e);return 2;}}
}
